package security

import "testing"

// Native vectors were generated by the pinned actual packaged Argon encoder.
// 原版组件受控输入生成的冻结向量，不含账户凭据。
func TestSecurityNativeArgonReference(t *testing.T) {
	cases := []struct {
		raw, encoded string
		want         bool
	}{
		{"Controlled-ASCII-123!", "argon$$argon2id$v=19$m=512,t=16,p=1$X1U4bV8v22ZJgV14BJcGqQ$ZPpzcjYPjTxQLP+fnwXyoKQ9eR0qW2iNdrjLutEzABo", true},
		{"密码-é-😀", "argon$$argon2id$v=19$m=512,t=16,p=1$+BXTpeh+UxrfoGMqKxsZGA$mMctjEaKngY2eBAka5tR9woSfTW0EZrYjSFhOGxyaSU", true},
		{"", "argon$$argon2id$v=19$m=512,t=16,p=1$Na4c8I1bVGYA8ifS0hulig$93GQP3TX1sGDTM1Y/PoXFlbI4xsW28hoTB4kGVV4l4Y", false},
		{"", "argon$$argon2id$v=19$m=512,t=16,p=1$CKGpIxn0tPOgvXK6tI3nwA$Q28jIQmpCx3v/NCP+B7ur9/CGEtKNr5xTqlIpMf9oMg", true},
		{"  padded  ", "argon$$argon2id$v=19$m=512,t=16,p=1$Iq3eM+SV66jDwdwR0RKw+g$qvI1qp05LD5iJ/gGmScxK7wZNRlXgnyzkWYVpmW3RiM", true},
		{"a\u0000b", "argon$$argon2id$v=19$m=512,t=16,p=1$FYbm7J1KgWB+7qEAxVkQhA$rw0idC+0TK5awjXhSN2FflW4rgdWPSJstlI+RxJwiLo", true},
		{"é", "argon$$argon2id$v=19$m=512,t=16,p=1$EC+VjznEmecMRHRM/nq3Dw$OfMjBaiRyV6r2ClXz3yQOVnWIrdJbQV3vcxVRZ3aoX8", true},
		{"é", "argon$$argon2id$v=19$m=512,t=16,p=1$KlXkWHJfon+CgxXyl8oCZw$+RwqVXc5oqyj9vi3imt1YeVfALwWQsQ2Jb7WImGbEbg", true},
		{"Controlled-ASCII-123!", "argon$$argon2id$v=19$m=512,t=16,p=1$RTStndJ43Gn9cTUmhdJSGg$T57xNdVzVecWNtH88qxkvP+72MjNVJa8rjQjFEwn/0o", true},
	}
	for i, c := range cases {
		ok, err := CheckCredential(c.raw, c.encoded)
		if err != nil || ok != c.want {
			t.Fatalf("native vector %d: ok=%v err=%v", i, ok, err)
		}
		if c.want {
			ok, err = CheckCredential(c.raw+"!", c.encoded)
			if err != nil || ok {
				t.Fatalf("changed raw vector %d accepted", i)
			}
		}
	}
}
